def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    products = doc.products
    cam = adsk.cam.CAM.cast(products.itemByProductType('CAMProductType'))
    setup = cam.setups.item(0)
    print("Setup:", setup.name)
    # WCS
    try:
        params = setup.parameters
        for i in range(params.count):
            p = params.item(i)
            try:
                print(" param:", p.name, "=", p.value.value if hasattr(p.value,'value') else p.value)
            except:
                print(" param:", p.name)
    except Exception as e:
        print("param err", e)
    return "done"

def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    camMgr = adsk.cam.CAMManager.get()
    libMgr = camMgr.libraryManager
    toolLibs = libMgr.toolLibraries
    # find TIW library
    def walk(url, depth=0):
        for u in toolLibs.childAssetURLs(url):
            print("  "*depth+"[folder]", u.leafName)
            walk(u, depth+1)
        for u in toolLibs.childReferenceURLs(url):
            print("  "*depth+"[lib]", u.leafName, u.toString())
    roots = [adsk.cam.LibraryLocations.LocalLibraryLocation,
             adsk.cam.LibraryLocations.Fusion360LibraryLocation]
    for loc in roots:
        try:
            url = toolLibs.urlByLocation(loc)
            print("LOCATION", loc)
            walk(url)
        except Exception as e:
            print("err",loc,e)
    return "done"

