def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    toolLibs = adsk.cam.CAMManager.get().libraryManager.toolLibraries
    def find(url):
        for u in toolLibs.childAssetURLs(url):
            if 'TIW' in u.leafName: return u
            r=find(u)
            if r: return r
    lib = toolLibs.toolLibraryAtURL(find(toolLibs.urlByLocation(0)))
    want={50:'face',52:'rough',9:'finish4mm',37:'drill14',45:'spot',53:'cbore'}
    for i in range(lib.count):
        t=lib.item(i)
        num=t.parameters.itemByName('tool_number').value.value
        if num in want:
            print(num, want[num], "dia_cm=",t.parameters.itemByName('tool_diameter').value.value,
                  "desc=",t.parameters.itemByName('tool_description').value.value)
    return "done"

